import ast
import json
import re
from pathlib import Path


def parse_json_maybe(value):
    if value is None:
        return {}
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return {}
        ticks = chr(96) * 3
        if text.startswith(ticks):
            text = re.sub("^" + ticks + r"(?:json)?\s*", "", text, flags=re.I).strip()
            if text.endswith(ticks):
                text = text[:-3].strip()
        for parser in (json.loads, ast.literal_eval):
            try:
                parsed = parser(text)
                return parsed if isinstance(parsed, dict) else {}
            except Exception:
                pass
    return {}


def clean(value, fallback=""):
    if value in (None, "", [], {}):
        return fallback
    if isinstance(value, (dict, list)):
        value = json.dumps(value, ensure_ascii=False)
    return re.sub(r"\s+", " ", str(value)).strip() or fallback


def as_list(value):
    return value if isinstance(value, list) else []


FIELD_LABEL_MAP = {"close date": "Close"}
LONG_VALUE_THRESHOLD = 36
EMPTY_MARKERS = {"", "-", "unknown", "n/a", "none", "null", "tbd", "no change", "not changed"}


def is_meaningful(value):
    return clean(value, "").strip().lower() not in EMPTY_MARKERS


def format_field_value(field_label, new_value):
    if field_label.strip().lower() == "amount":
        raw = new_value.replace(",", "").replace("$", "").strip()
        try:
            amount = float(raw)
            return "${:,.2f}".format(amount)
        except ValueError:
            return new_value
    return new_value


def build_opportunity_details(data, fallback_name=""):
    name = clean(data.get("opportunity_name") or fallback_name, "Unknown Opportunity")
    account_raw = clean(data.get("account_name"), "")
    industry = clean(data.get("account_industry"), "")
    account_display = " · ".join(p for p in [account_raw, industry] if p) or "Unknown Account"
    opp_id = clean(data.get("opportunity_id"), "Unknown")
    return "\n".join([
        f"**Name: ** {name}",
        f"**Account: ** {account_display}",
        f"**ID: ** {opp_id}",
    ])


def build_updated_fields(data):
    raw_fields = [item for item in as_list(data.get("updated_fields"))[:6] if isinstance(item, dict)]
    compact_pairs = []
    long_pairs = []
    for item in raw_fields:
        field = clean(item.get("field"), "Field")
        label = FIELD_LABEL_MAP.get(field.strip().lower(), field)
        value = format_field_value(label, clean(item.get("new_value"), ""))
        if not is_meaningful(value):
            continue
        if len(value) > LONG_VALUE_THRESHOLD:
            long_pairs.append((label, value))
        else:
            compact_pairs.append((label, value))

    lines = [f"{label} {value}" for label, value in compact_pairs]
    lines.extend(f"{label}: {value}" for label, value in long_pairs)
    if not lines:
        lines = ["Completed - review Salesforce for changed fields"]
    return "\n".join(lines)


def build_source_line(data):
    account_raw = clean(data.get("account_name"), "")
    meeting_date = clean(data.get("meeting_date"), "")
    meeting_display = " · ".join(p for p in [account_raw, meeting_date] if p) or "-"
    return f"Meeting {meeting_display}"


def resolve_url(data, fallback_url=""):
    return clean(data.get("opportunity_url") or fallback_url, "")


def run_node(input_data, context=None):
    input_data = input_data or {}
    try:
        data = parse_json_maybe(input_data.get("result_json"))
        fallback_name = input_data.get("name", "")
        fallback_url = input_data.get("url", "")
        return {
            "success": True,
            "output": {
                "opportunity_details": build_opportunity_details(data, fallback_name),
                "updated_fields": build_updated_fields(data),
                "source_line": build_source_line(data),
                "salesforce_url": resolve_url(data, fallback_url),
            },
        }
    except Exception as exc:
        return {
            "success": True,
            "output": {
                "opportunity_details": "Update completed - review Salesforce for details.",
                "updated_fields": "",
                "source_line": "",
                "salesforce_url": input_data.get("url", ""),
            },
            "error": str(exc),
        }


if __name__ == "__main__":
    try:
        request = json.loads(Path(__file__).with_name("request.json").read_text(encoding="utf-8"))
        result = run_node(request.get("input_data", {}), request.get("context", {}))
    except Exception as exc:
        result = {
            "success": True,
            "output": {
                "opportunity_details": "Update completed - review Salesforce for details.",
                "updated_fields": "",
                "source_line": "",
                "salesforce_url": "",
            },
            "error": str(exc),
        }
    print(json.dumps(result, ensure_ascii=False))

